import PropTypes from 'prop-types';
import { NavLink as RouterLink } from 'react-router-dom';
// @mui
import { Box, List, ListItemText, Button, Collapse } from '@mui/material';
import { useState } from 'react';
import Divider from '@mui/material/Divider';
import { PUBLIC_URL } from '../../utils/config';
//
import { StyledNavItem, StyledNavItemIcon } from './styles';
import Iconify from '../iconify';


NavSection.propTypes = {
  data: PropTypes.arrayOf(PropTypes.object),
};

export default function NavSection({ data = [], ...other }) {
  return (
    <Box {...other}>
      <List disablePadding sx={{ p: 1 }}>
        {data.map((item, index) => (
          <NavItem key={index} item={item} />
        ))}
      </List>
    </Box>
  );
}

NavItem.propTypes = {
  item: PropTypes.object,
};

function NavItem({ item }) {
  const { title, path, icon, info, options, optionTitle } = item;
  const [showOptions, setShowOptions] = useState(false);
  const handleToggleOptions = () => {
    setShowOptions(!showOptions);
  };
  const params = new URLSearchParams(window.location.search);
  const type = params.get('type');

  return (
    <>
      {item.isHeader && <ListItemText disableTypography primary={item.title} sx={{ color: "#333", margin: "8px 0px 10px 10px", fontWeight: "700" }} />}
      {item.isdivider && <Divider sx={{backgroundColor:"#DDDDDD",width:"90%",height:"2px",margin:"20px auto",borderRadius:"10%"}}/>}
      {title && !item.isHeader &&
        <StyledNavItem
          component={RouterLink}
          to={path}
          sx={{
            '&.active': {
              color: 'text.primary',
              bgcolor: 'action.selected',
              fontWeight: 'fontWeightBold',
            },
          }}
        >
          <StyledNavItemIcon >{icon && icon}</StyledNavItemIcon>
          <ListItemText disableTypography primary={title} sx={{ color: "#1f2937", fontSize: "16px", fontWeight: '600' }} />
          {info && info}
        </StyledNavItem>}

      {options && options.length > 0 && (
        <>
          <Button 
            disableRipple
            onClick={handleToggleOptions}
            sx={{
              width: '100%',
              color: '#1f2937',
              margin: '0px 0px',
              padding: '10px 0px',
              fontWeight: "400",
              '&:hover': {
                background: '#e8ebee', /* #919eab14 */
              },
              ...(showOptions && {
                background: '#e8ebee',
                color: '#1f2937',
                margin: '0px 0px',
                padding: '10px 0px',
              }),
            }}
          >
            {showOptions ? (
              <>
                <StyledNavItemIcon>
                  <StyledNavItemIcon>{icon && icon}</StyledNavItemIcon>
                  {/* <img src={`${PUBLIC_URL}/assets/icons/navbar/ic_disabled.svg`} alt="" style={{ width: 16, height: 16 }} /> */}
                </StyledNavItemIcon>
                <ListItemText sx={{ textAlign: 'start', color: "#1f2937", fontSize: "16px", fontWeight: '600' }} disableTypography primary={optionTitle} />
                <Button 
                  disableRipple 
                  sx={{
                    '&:hover': {
                      background: 'transparent',
                    }
                  }}
                  startIcon={<Iconify icon="il:arrow-up" color="#a4abb3" style={{ width: '13px', height: '13px' }} />}
                />
              </>
            ) : (
              <>
                <StyledNavItemIcon>
                  <StyledNavItemIcon>{icon && icon}</StyledNavItemIcon>
                  {/* <img src={`${PUBLIC_URL}/assets/icons/navbar/ic_disabled.svg`} alt="" style={{ width: 16, height: 16 }} /> */}
                </StyledNavItemIcon>
                <ListItemText sx={{ textAlign: 'start', color: "#1f2937", fontSize: "16px", fontWeight: '600' }} disableTypography primary={optionTitle} />
                <Button 
                  disableRipple 
                  sx={{
                    '&:hover': {
                      background: 'transparent',
                    }
                  }}
                  startIcon={<Iconify icon="il:arrow-down" color="#a4abb3" style={{ width: '13px', height: '13px' }} />}
                />
              </>
            )}
          </Button>

          <Collapse in={showOptions} timeout={300}>
            <List>
              {options.map((option) => (
                <StyledNavItem key={option.title} component={RouterLink} to={option.path} /* sx={{
                  '&.active': {
                    color: 'text.primary',
                    bgcolor: 'action.selected',
                    fontWeight: 'fontWeightBold',
                  },
                }} */>
                  <StyledNavItemIcon>{option.icon && option.icon}</StyledNavItemIcon>
                  <ListItemText disableTypography primary={option.title} sx={{ color: "#1f2937" }} />
                  {option.info && option.info}
                </StyledNavItem>
              ))}
            </List>
          </Collapse>
        </>
      )}
    </>
  );
}
