import { useState, Suspense,useMemo } from 'react';
import { Outlet, useLocation, Navigate, useOutlet } from 'react-router-dom';
// @mui
import { styled } from '@mui/material/styles';
import { CSSTransition, SwitchTransition } from 'react-transition-group'
import { useMyContext } from 'src/pages/provider';
import { DashboardRoutes } from '../../routes/routes'
import Loader from '../../routes/Loader';
//
import ScrollToTop from '../../components/scroll-to-top';
import Header from './header';
import Nav from './nav';
// ----------------------------------------------------------------------
const APP_BAR_MOBILE = 64;
const APP_BAR_DESKTOP = 60;
const StyledRoot = styled('div')({
  display: 'flex',
  minHeight: '100%',
  height: '100%'
});
const Main = styled('div')(({ theme }) => ({
  flexGrow: 1,
  minHeight: '100%',
  height: '100%',
  paddingTop: APP_BAR_MOBILE + 24,
  backgroundColor:"white",
  paddingBottom: theme.spacing(10),
  paddingLeft: theme.spacing(2),
  paddingRight: theme.spacing(2),
  [theme.breakpoints.up('lg')]: {
    paddingTop: APP_BAR_DESKTOP + 24,
    paddingLeft: theme.spacing(3),
    paddingRight: theme.spacing(3),
  },
}));
// ----------------------------------------------------------------------
const guestRoutes = ["/dashboard/profile", "/dashboard", "/dashboard/app",'/dashboard/AdminProfile','/dashboard/Notifications',"/dashboard/Sendnotification",'/dashboard/adminroles']

export default function DashboardLayout() {
  const [open, setOpen] = useState(false);
  const location = useLocation();
  const currentOutlet = useOutlet()
  const { nodeRef } = DashboardRoutes.find((route) => route.path === location.pathname) ?? {}
  const currentUrl = location.pathname;
  const { MappedNav } = useMyContext()
  console.log("currentUrl", currentUrl)
  console.log("MappedNav", MappedNav)
  const validRoutes = useMemo(() => {
    const obj = {};
    const regexRoutes = [];
    MappedNav.forEach(element => {
      // debugger
      if (element.path) {        
        obj[element.path] = true;
      }
      if (element.options && Array.isArray(element.options)) {
        element.options.forEach((subelem) => {
          if (subelem.path) {
            const cleanUrl = subelem.path.split('?')[0];
            obj[cleanUrl] = true;
          }
          if (subelem.urls && Array.isArray(subelem.urls)) {
            subelem.urls.forEach((suburl) => {
              if (suburl.includes('{')) { // regex /user/{id}/{active}
                regexRoutes.push(suburl);
              } else {
                obj[suburl] = true
              }
            })
          }
        })
      }
      if (element.urls && Array.isArray(element.urls)) {
        element.urls.forEach((suburl) => {
          if (suburl.includes('{')) { // regex /user/{id}/{active}
            regexRoutes.push(suburl);
          } else {
            obj[suburl] = true
          }
        })
      }
    });
    return {
      regular: obj,
      regex: regexRoutes
    };
  }, [MappedNav]) // all path will be saved to validRoutes as key value pair
  console.log("validroutesss", validRoutes, currentUrl)
  // Function to check if a route matches the current URL
  const matchRoute = (routePath, currentPath) => {
    // debugger
    const dynamicSegmentRegex = /\{[^}]+\}/g; // Matches dynamic segments like {userid}
    if (typeof routePath !== 'string') return false;
    const routeRegex = new RegExp(`^${routePath.replace(dynamicSegmentRegex, '[^/]+')}$`);
    return routeRegex.test(currentPath);
  };
  const isValidPath = useMemo(() => {
    if(guestRoutes.includes(location.pathname)){
      return true
    }
    if (Object.keys(validRoutes.regular).length > 0) {
      if (validRoutes.regular[location.pathname]) { // direct url without any need of regex
        return true;
      }
      validRoutes.regex.find((route) => { // loop all routes and check regex
        // debugger
        if (!route || typeof route.path !== 'string') return false;
        return matchRoute(route.path, location.pathname);
      })
      return false;
    }
    return true;
  }, [validRoutes, location.pathname])
  console.log("findinMenu", isValidPath);
  if (MappedNav.length > 0 && !isValidPath) {
    // debugger
    // return <Navigate to="/404" state={{ from: location }} replace />;
    console.log("isssue found")
  }
  if (!localStorage.getItem('admintoken')) {
    // Redirect them to the /login page, but save the current location they were
    // trying to go to when they were redirected. This allows us to send them
    // along to that page after they login, which is a nicer user experience
    // than dropping them off on the home page.
    return <Navigate to="/login" state={{ from: location }} replace />;
  }
  return (
    <StyledRoot>
      <Header onOpenNav={() => setOpen(true)} />
      <Nav openNav={open} onCloseNav={() => setOpen(false)} />
      <Main>
      <Suspense fallback={Loader}>
      <SwitchTransition>
          <CSSTransition
            key={location.pathname+location.search}
            nodeRef={nodeRef}
            timeout={0}
            classNames="page"
            unmountOnExit
          >
              {(state) => (
              <div ref={nodeRef} className="page">
                {currentOutlet}
              </div>
            )}
          </CSSTransition>
        </SwitchTransition>
        </Suspense>
      </Main>
      <ScrollToTop />
    </StyledRoot>
  );
}