import PropTypes from 'prop-types';
import { useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
// import { toast } from 'react-toastify';

// @mui
import { styled, alpha } from '@mui/material/styles';
import { Box, Link, Drawer, Typography, Avatar} from '@mui/material';
// mock

// import account from '../../../_mock/account';
// hooks
import useResponsive from '../../../hooks/useResponsive';
// components
// import Logo from '../../../components/logo';
import { Logo } from '../../../svg';
import Scrollbar from '../../../components/scrollbar';
import NavSection from '../../../components/nav-section';
import { axios } from '../../../utils/axios';
import { IMAGE_URL } from '../../../utils/config';
// import navConfig from './config';
import useNavConfigComponent from './config';
import { useMyContext } from '../../../pages/provider';
import GenerateToastConfig from '../../../components/toast-config/GenerateToastConfig';

// ----------------------------------------------------------------------

const NAV_WIDTH = 290;

const StyledAccount = styled('div')(({ theme }) => ({
  display: 'flex',
  alignItems: 'center',
  padding: theme.spacing(2, 2.5),
  borderRadius: Number(theme.shape.borderRadius) * 1.5,
  backgroundColor: alpha(theme.palette.grey[500], 0.12),
}));

// ----------------------------------------------------------------------

Nav.propTypes = {
  openNav: PropTypes.bool,
  onCloseNav: PropTypes.func,
};

export default function Nav({ openNav, onCloseNav }) {
  const { myValue, imageUrl ,MappedNav} = useMyContext();
  console.log("navconfiggg",MappedNav)

  const { pathname } = useLocation();
  const navigate = useNavigate();
  // const [imageUrl, setImageUrl] = useState(null);
  const [data, setData] = useState(null);
  // const [open, setOpen] = useState(false)

  const isDesktop = useResponsive('up', 'lg');

  useEffect(() => {
    if (openNav) {
      onCloseNav();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pathname]);

  const openModal = async () => {
    const token = localStorage.getItem('admintoken');
    const id = localStorage.getItem('adminid');
    const headers = {
      Authorization: `${token}`,
      'Content-Type': 'application/json',
    };
    try {
      const res = await axios.get(`module/auth/admin/${id}`, { headers });
      if (res.status === 200) {
        navigate('/dashboard/editprofile', { state: { datas: res.data.data, editId: id, types: res.data.type } });
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };
  const AdminProfileData = async () => {
    try {
      const res = await axios.get('module/auth/admin/profile');
      if (res.status === 200) {
        setData(res?.data?.data?.profileData);
        console.log("profiledata",res?.data?.data?.profileData.role.permission)
        // setImageUrl(res?.data?.data?.profileImage);
      }
    } catch (err) {
      console.log(err);
    }
  };
  useEffect(() => {
    AdminProfileData();
  }, []);
  const handlenavigate = () => {
    navigate('/dashboard/AdminProfile');
  };
  const handleLogo = () => {
    navigate('/dashboard');
  };

  // const navConfig = useNavConfigComponent();

  
  const renderContent = (
    <Scrollbar
      sx={{
        // height: 1,
        '& .simplebar-content': { height: 1, display: 'flex', flexDirection: 'column' ,backgroundColor:"white"},
      }}
    >
      <Box sx={{ px: 3, py: 3, display: 'inline-flex', justifyContent: 'flex-start',cursor: 'pointer' }} onClick={handleLogo}>
        <Logo height="80px" color="red" />
        {/* <img src='/webadmin/purplerooms.png' alt='img' style={{
                height:'80px'
              }}/> */}
      </Box>

      <Box sx={{ mb: 3, mx: 2.5, cursor: 'pointer' ,display: 'inline-flex',justifyContent: 'flex-start'}}>
        <Link underline="none" onClick={handlenavigate}>
          <StyledAccount>
            <Avatar src={IMAGE_URL + imageUrl} alt="photoURL" />

            <Box sx={{ ml: 2 }}>
              <Typography variant="subtitle2" sx={{ color: 'text.primary', textTransform: 'capitalize',fontSize:"20px" }}>
                {myValue?.firstname}
                &nbsp;
                {myValue?.lastname}
              </Typography>

              <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                {myValue?.email}
              </Typography>
            </Box>
          </StyledAccount>
        </Link>
      </Box>

      <NavSection data={MappedNav} />

      <Box sx={{ flexGrow: 1 }} />
    </Scrollbar>
  );

  return (
    <>
      <Box
        component="nav"
        sx={{
          flexShrink: { lg: 0 },
          width: { lg: NAV_WIDTH },
        }}
      >
        {isDesktop ? (
          <Drawer
            open
            variant="permanent"
            PaperProps={{
              sx: {
                width: NAV_WIDTH,
                bgcolor: 'background.default',
                // borderRightStyle: 'dashed',
              },
            }}
          >
            {renderContent}
          </Drawer>
        ) : (
          <Drawer
            open={openNav}
            onClose={onCloseNav}
            ModalProps={{
              keepMounted: true,
            }}
            PaperProps={{
              sx: { width: NAV_WIDTH },
            }}
          >
            {renderContent}
          </Drawer>
        )}
      </Box>
    </>
  );
}
