const LanguageModal = ({ open, onClose }) => {
    // const lan = getCookie("NEXT_LANG");
    // const [selectedLanguage, setSelectedLanguage] = useState(lan || "");
    // const [lang, setLang] = useState();
    const [languages, setLanguages] = useState([])
    const { setState, i18 } = useMyContext()

    // const StyledListItem = styled(ListItem)(({ theme, selected }) => ({
    //     border: selected ? '2px solid black' : 'none',
    // }));

    const handleSelectedLanguage = (data) => {
        setState(true)
        // setSelectedLanguage(data || lan);
        // setLang(langName);
        const newLocale = data;
        setCookie('NEXT_LOCALE', newLocale)
        // setCookie('NEXT_LANG', langName || "English")
        // document.cookie = `NEXT_LOCALE=${newLocale}`;
        // document.cookie = `NEXT_LANG=${langName || "English"}`;
        window.location.reload();
        onClose()
    }
    useEffect(() => {
        getLanguageApi();
    }, [])

    const getLanguageApi = async () => {
        try {
            const url = `/module/translation/languages/user`
            const response = await axios.get(url)
            if (response && response.status === 200) {
                setLanguages(response.data.data.language)
            }
        } catch (error) {
            console.error('Error fetching languages:', error);
        }
    }
    return (
        <Dialog open={open} onClose={onClose} fullWidth maxWidth="md">
            <DialogTitle>
                {i18?.LANGUAGEMODAL?.LANGUAGEREGION || "Choose a Language and Region"}
            </DialogTitle>
            <DialogContent>
                <List>
                    <Grid container spacing={2}>
                        {languages.map((item, index) => (
                            <Grid item xs={6} sm={3} key={index}>
                                <ListItem button onClick={() => handleSelectedLanguage(item.indexName)}>
                                    <ListItemText
                                        primary={item.name}
                                        secondary={item.indexName}
                                    />
                                </ListItem>
                                {/* {index % 2 === 1 && <Divider />} */}
                                {(index + 1) % 2 === 0 && index !== languages.length - 1 && <Divider variant="middle" />}
                            </Grid>
                        ))}
                    </Grid>
                </List>

            </DialogContent>
            <DialogActions>
                <Button onClick={onClose} color="primary">
                    {i18?.LANGUAGEMODAL?.CLOSE || "Close"}
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default LanguageModal;