// utils/urlUtils.js for getting pagination values
import { IMAGE_URL } from "./config";

export const updateUrlParams = (params) => {
  const urlSearchParams = new URLSearchParams(window.location.search);

  Object.keys(params).forEach(key => {
    urlSearchParams.set(key, params[key].toString());
  });

  const newUrl = `${window.location.pathname}?${urlSearchParams.toString()}`;
  window.history.replaceState(null, '', newUrl);
};

export const handleImageError = (e) => {
  if (!e.target.hasAttribute('data-error-handled')) {
    e.target.srcset = '';
    e.target.src = '/webadmin/images/errorImage.webp';
    e.target.setAttribute('data-error-handled', 'true');
    e.target.onerror = function () {
      try {
        e.preventDefault()
      } catch (err) {
        console.log('ImageError:', err)
      }
    };
  };
};

export const handleSVGError = (e) => {
  // Check if the error handler has already run for this image
  if (!e.target.hasAttribute('data-error-handled')) {
    e.target.srcset = '';
    e.target.src = 'data:image/svg+xml;base64,'
    e.target.width = 30;
    e.target.height = 30;

    // Mark this image as having its error handled
    e.target.setAttribute('data-error-handled', 'true');

    e.target.onerror = function () {
      try {
        e.preventDefault(); // Prevent default error handling
      } catch (err) {
        console.log('ImageError:', err);
      }
    };
  }
};
