import { useMyContext } from './pages/provider';
import { IMAGE_URL } from './utils/config';
import { handleSVGError } from './utils/urlUtilis';

export const Logo = (props) => {
  const data = useMyContext();
  return (
    <img
      src={IMAGE_URL + data.logo}
      alt="Company Logo"
      height={props.height || "40px"}
      style={{ margin: '0 auto' }}
      onError={handleSVGError}
    />
  );
};

export const Starlogo = (props) => {
  const data = useMyContext();
  return (
    <img 
      src={IMAGE_URL + data.favicon} 
      alt="Favicon" 
      width="auto" 
      height="35px"
      onError={handleSVGError}
    />
  );
};
