export default function AccountPopover() {
  const { myValue, imageUrl, i18 } = useMyContext();
  const theme = useTheme();
  const [open, setOpen] = useState(null);
  const [langOpen, setLangOpen] = useState(false);
  const navigate = useNavigate();

  const MENU_OPTIONS = [
    {
      label: i18?.ACCOUNTPOPOVER?.DASHBOARD || 'Dashboard',
      icon: 'eva:home-fill',
      path: '/dashboard/app',
    },
    {
      label: i18?.ACCOUNTPOPOVER?.PROFILE || 'Profile',
      icon: 'eva:person-fill',
      path: '/dashboard/AdminProfile',
    },
  ];

  // const lang = getCookie("NEXT_LANG") ? getCookie("NEXT_LANG") : 'English';

  const logOut = () => {
    localStorage.removeItem('admintoken');
    localStorage.removeItem('adminid');
    localStorage.removeItem('adminmail');
    localStorage.removeItem('adminname');
    localStorage.removeItem('adminlastname');
    setOpen(null);
    navigate('/login');
  };
  

  const handleOpen = (event) => {
    setOpen(event.currentTarget);
  };

  const handleSendIconClick = () => {
    navigate('/dashboard/Sendnotification');
  };

  const handleViewNotification = () => {
    navigate('/dashboard/Notifications');
  };

  const handleLanguageModal = () => {
    setLangOpen(true);
  };

  const handleLanguageModalClose = () => {
    setLangOpen(false);
  };

  return (
    <>
      <a href={window.origin} rel="noreferrer" target='_blank'>
        <Starlogo width="34" height="34" style={{ fill: 'red' }} />
      </a>
      <div style={{ marginRight: '15px', cursor: 'pointer' }}>
        <NotificationsNoneIcon sx={{ color: 'black' }} onClick={handleViewNotification} />
      </div>

      <div style={{ position: 'relative', marginRight: '15px', cursor: 'pointer' }}>
        <Tooltip>
          <PublicIcon sx={{ color: '#0A6EBD' }} onClick={handleLanguageModal} />
        </Tooltip>
      </div>


      <div style={{ marginRight: '15px', cursor: 'pointer' }}>
        <SendRoundedIcon sx={{ color: '#0A6EBD' }} onClick={handleSendIconClick} />
      </div>
      <IconButton
        onClick={handleOpen}
        sx={{
          p: 0,
          ...(open && {
            '&:before': {
              zIndex: 1,
              content: "''",
              width: '100%',
              height: '100%',
              borderRadius: '50%',
              position: 'absolute',
              bgcolor: (theme) => alpha(theme.palette.grey[900], 0.8),
            },
          }),
        }}
      >
        <Avatar sx={{ boxShadow: 2 }} src={IMAGE_URL + imageUrl} alt="photoURL" />
      </IconButton>

      <Popover
        open={Boolean(open)}
        anchorEl={open}
        onClose={() => setOpen(null)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
        PaperProps={{
          sx: {
            p: 0,
            mt: 1.5,
            ml: 0.75,
            width: 180,
            bgcolor: theme.palette.mode === 'dark' ? '#000' : '#FFF',
            '& .MuiMenuItem-root': {
              typography: 'body2',
              borderRadius: 0.75,
            },
          },
        }}
      >
        <Box sx={{ my: 1.5, px: 2.5 }}>
          <Typography variant="subtitle2" noWrap sx={{ textTransform: 'capitalize' }}>
            {myValue?.firstname}
            &nbsp;
            {myValue?.lastname}
          </Typography>
          <Typography variant="body2" sx={{ color: 'text.secondary' }} noWrap>
            {myValue?.email}
          </Typography>
        </Box>

        {/* <Divider sx={{ borderStyle: 'dashed' }} /> */}
        <Divider/>

        <List>
          {MENU_OPTIONS.map((option) => (
            <StyledNavItem sx={{ p: 1 }} key={option.label} component={RouterLink} to={option.path}>
              <StyledNavItemIcon>
                <Iconify icon={option.icon} />
              </StyledNavItemIcon>
              <ListItemText disableTypography primary={option.label} onClick={() => setOpen(null)} />
            </StyledNavItem>
          ))}
        </List>

        {/* <Divider sx={{ borderStyle: 'dashed' }} /> */}
        <Divider/>

        <MenuItem onClick={logOut} sx={{ m: 1 }}>
          <Iconify sx={{ mr: 1 }} icon="material-symbols:logout" />
          {i18?.ACCOUNTPOPOVER?.LOGOUT || "Logout"}
        </MenuItem>
      </Popover>

      <LanguageModal open={langOpen} onClose={handleLanguageModalClose} />
    </>

  );
}
